/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject, pruneStaleDocuments
 */
import { createLogger } from "@/lib/logger";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
  pruneStaleDocuments,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId, Page } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Walks one tenant's live projects, issues and comments and re-upserts every
 * document. Scoped to a single org on purpose: a full-fleet reindex is a
 * sequence of these, so one slow tenant cannot stall the rest.
 *
 * Every listing is followed to its last page, so a backlog larger than one
 * page is indexed in full. Only live rows are indexed. When the walk finishes
 * cleanly, documents it did not re-upsert are pruned, so the index matches the
 * live content exactly.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    // Stamped before the first read: every document the walk writes is at or
    // after this instant, so anything older is stale once the walk completes.
    const rebuildStartedAt = toIsoTimestamp(new Date());

    await forEachPage(
      (cursor) => projectRepo.listProjects({ orgId, limit: PAGE_SIZE, cursor }),
      async (project) => {
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    // Archived issues leave the index with their issue.archived event, so the
    // rebuild walks only the live ones.
    await forEachPage(
      (cursor) =>
        issueRepo.listIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: false,
        }),
      async (issue) => {
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;

          // Live comments only, at any reply depth. A live reply whose parent
          // was deleted is still live, so it is still indexed.
          await forEachPage(
            (cursor) =>
              commentRepo.listComments({
                orgId,
                issueId: issue.id,
                limit: PAGE_SIZE,
                cursor,
                includeArchived: false,
              }),
            async (comment) => {
              await indexComment(orgId, comment);
              result.processed += 1;
            },
          );
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    // With failures, an untouched document may still be live, so pruning would
    // drop content the rebuild could not re-index. Keep what is there instead.
    if (result.failed === 0) {
      await pruneStaleDocuments(orgId, rebuildStartedAt);
    } else {
      logger.warn("skipped pruning stale documents after failures", {
        failed: result.failed,
      });
    }
  });
}

/**
 * Visits every item of a keyset-paged listing, following `nextCursor` until the
 * last page. Reading only the first page would silently skip the oldest rows.
 */
async function forEachPage<T>(
  fetchPage: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page: Page<T> = await fetchPage(cursor);
    for (const item of page.items) {
      await visit(item);
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
}

