import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("scratchsearch", "growth");
  other = await createTenant("scratchother", "growth");
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

const find = (q: string, kinds: ("issue" | "comment" | "project")[], t: Tenant = tenant) =>
  searchService.search(t.actors.member, {
    orgId: t.org.id,
    q,
    kinds,
    limit: 25,
    cursor: null,
  });

async function newIssue(title: string, t: Tenant = tenant) {
  return issueService.createIssue(
    t.actors.member,
    issueInput(t.org.id, t.project.id, { title }),
  );
}

async function comment(issueId: string, body: string, parentId: string | null = null, t: Tenant = tenant) {
  return commentService.createComment(t.actors.member, {
    orgId: t.org.id,
    issueId: issueId as never,
    body,
    parentId: parentId as never,
    mentionedUserIds: [],
  });
}

describe("scratch: search fix", () => {
  it("1: issue comment count excludes deleted, includes replies", async () => {
    const issue = await newIssue("CountIssueScratch");
    const top = await comment(issue.id, "CntTopScratch");
    await comment(issue.id, "CntReplyScratch", top.id);
    const gone = await comment(issue.id, "CntGoneScratch");
    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: gone.id,
    });

    const detail = await issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(detail.commentCount).toBe(2);
  });

  it("2: deleting a comment removes only that comment from search", async () => {
    const issue = await newIssue("DelScopeIssueScratch");
    const top = await comment(issue.id, "DelScopeTopScratch");
    await comment(issue.id, "DelScopeReplyScratch", top.id);

    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: top.id,
    });

    expect((await find("DelScopeTopScratch", ["comment"])).total).toBe(0);
    expect((await find("DelScopeReplyScratch", ["comment"])).total).toBe(1);
    expect((await find("DelScopeIssueScratch", ["issue"])).total).toBe(1);
  });

  it("3: archiving an issue removes its comments and replies only", async () => {
    const a = await newIssue("ArchScopeAScratch");
    const ca = await comment(a.id, "ArchCmtAScratch");
    await comment(a.id, "ArchReplyAScratch", ca.id);
    const b = await newIssue("ArchScopeBScratch");
    await comment(b.id, "ArchCmtBScratch");

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, a.id);

    expect((await find("ArchScopeAScratch", ["issue"])).total).toBe(0);
    expect((await find("ArchCmtAScratch", ["comment"])).total).toBe(0);
    expect((await find("ArchReplyAScratch", ["comment"])).total).toBe(0);
    expect((await find("ArchCmtBScratch", ["comment"])).total).toBe(1);
  });

  it("4: rebuild indexes exactly the live content and is idempotent", async () => {
    const archived = await newIssue("RbArchivedIssueScratch");
    await comment(archived.id, "RbArchivedIssueCmtScratch");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    const live = await newIssue("RbLiveIssueScratch");
    const parent = await comment(live.id, "RbDeletedParentScratch");
    await comment(live.id, "RbLiveReplyScratch", parent.id);
    const deleted = await comment(live.id, "RbDeletedCommentScratch");
    await commentService.deleteComment(tenant.actors.member, { orgId: tenant.org.id, commentId: parent.id });
    await commentService.deleteComment(tenant.actors.member, { orgId: tenant.org.id, commentId: deleted.id });

    // Simulate drift: put archived / deleted content back into the index by hand.
    const archivedRow = await issueRepo.findIssueById(tenant.org.id, archived.id);
    await searchService.indexIssue(tenant.org.id, archivedRow!);
    const deletedRow = await commentRepo.findCommentById(tenant.org.id, deleted.id);
    await searchService.indexComment(tenant.org.id, deletedRow!);
    const archivedCmt = await comment(live.id, "RbNeverScratch");
    await commentService.deleteComment(tenant.actors.member, { orgId: tenant.org.id, commentId: archivedCmt.id });
    const archivedCmtRow = await commentRepo.findCommentById(tenant.org.id, archivedCmt.id);
    await searchService.indexComment(tenant.org.id, archivedCmtRow!);

    const otherIssue = await newIssue("RbOtherTenantScratch", other);
    await comment(otherIssue.id, "RbOtherTenantCmtScratch", null, other);
    const otherBefore = await searchRepo.countIndexed(other.org.id);

    const result1 = await runSearchReindexJob(tenant.org.id);
    expect(result1.failed).toBe(0);
    const countAfterFirst = await searchRepo.countIndexed(tenant.org.id);

    expect((await find("RbArchivedIssueScratch", ["issue"])).total).toBe(0);
    expect((await find("RbArchivedIssueCmtScratch", ["comment"])).total).toBe(0);
    expect((await find("RbDeletedCommentScratch", ["comment"])).total).toBe(0);
    expect((await find("RbDeletedParentScratch", ["comment"])).total).toBe(0);
    expect((await find("RbNeverScratch", ["comment"])).total).toBe(0);
    expect((await find("RbLiveReplyScratch", ["comment"])).total).toBe(1);
    expect((await find("RbLiveIssueScratch", ["issue"])).total).toBe(1);
    expect((await find("RbOtherTenantCmtScratch", ["comment"], other)).total).toBe(1);
    expect(await searchRepo.countIndexed(other.org.id)).toBe(otherBefore);

    await runSearchReindexJob(tenant.org.id);
    expect(await searchRepo.countIndexed(tenant.org.id)).toBe(countAfterFirst);
    expect((await find("RbLiveReplyScratch", ["comment"])).total).toBe(1);
  });

  it("5: rebuild covers every live issue and comment across pages", async () => {
    const userId = tenant.userIds.member;
    for (let i = 0; i < 250; i += 1) {
      const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, { title: `BulkIssue${i}Scratch` }),
        userId,
        number,
      );
    }
    const big = await newIssue("BulkThreadScratch");
    for (let i = 0; i < 250; i += 1) {
      await commentRepo.insertComment(
        {
          orgId: tenant.org.id,
          issueId: big.id,
          body: `BulkComment${i}Scratch`,
          parentId: null,
          mentionedUserIds: [],
        },
        userId,
      );
    }

    const result = await runSearchReindexJob(tenant.org.id);
    expect(result.failed).toBe(0);

    expect((await find("BulkIssue0Scratch", ["issue"])).total).toBe(1);
    expect((await find("BulkIssue249Scratch", ["issue"])).total).toBe(1);
    expect((await find("BulkComment0Scratch", ["comment"])).total).toBe(1);
    expect((await find("BulkComment249Scratch", ["comment"])).total).toBe(1);
    expect((await find("Scratch", ["comment"])).total).toBeGreaterThanOrEqual(250);

    const before = await searchRepo.countIndexed(tenant.org.id);
    await runSearchReindexJob(tenant.org.id);
    expect(await searchRepo.countIndexed(tenant.org.id)).toBe(before);
  });
});

